using System;
using System.Threading;
using System.Threading.Tasks;
using Confluent.Kafka;
using Confluent.SchemaRegistry;
using SolTechnology.Avro.Kafka;

// Start Kafka and Schema Registry first: docker compose -f samples/KafkaApp/docker-compose.yml up -d
const string topic = "orders";

using var schemaRegistry = new CachedSchemaRegistryClient(new SchemaRegistryConfig { Url = "http://localhost:8081" });

// The schema of Order is generated by AvroConvert and registered under "orders-value" on the first message.
using var producer = new ProducerBuilder<string, Order>(new ProducerConfig { BootstrapServers = "localhost:9092" })
    .SetAvroValueSerializer(schemaRegistry)
    .Build();

for (var i = 1; i <= 10; i++)
{
    var order = new Order { Id = i, Customer = $"customer-{i}", Total = Random.Shared.Next(10, 1000), CreatedAt = DateTime.UtcNow };
    await producer.ProduceAsync(topic, new Message<string, Order> { Key = i.ToString(), Value = order });
}

producer.Flush();
Console.WriteLine("Produced 10 orders. Consuming...");

using var consumer = new ConsumerBuilder<string, Order>(new ConsumerConfig
    {
        BootstrapServers = "localhost:9092",
        GroupId = "orders-sample",
        AutoOffsetReset = AutoOffsetReset.Earliest
    })
    .SetAvroValueDeserializer(schemaRegistry)
    .Build();

consumer.Subscribe(topic);
using var cancellation = new CancellationTokenSource(TimeSpan.FromSeconds(15));
try
{
    while (true)
    {
        var result = consumer.Consume(cancellation.Token);
        var o = result.Message.Value;
        Console.WriteLine($"{result.TopicPartitionOffset}: #{o.Id} {o.Customer} {o.Total:C} {o.CreatedAt:O}");
    }
}
catch (OperationCanceledException)
{
}
finally
{
    consumer.Close();
}

public class Order
{
    public int Id { get; set; }
    public string Customer { get; set; }
    public decimal Total { get; set; }
    public DateTime CreatedAt { get; set; }
}
